export const traditions = [johnTradition, ezekielTradition, treeTradition, plotinusTradition];
const planetNames = [
  ['moon', L('Moon', 'הירח', 'Луна')], ['mercury', L('Mercury', 'כוכב חמה', 'Меркурий')], ['venus', L('Venus', 'נוגה', 'Венера')],
  ['sun', L('Sun', 'השמש', 'Солнце')], ['mars', L('Mars', 'מאדים', 'Марс')], ['jupiter', L('Jupiter', 'צדק', 'Юпитер')], ['saturn', L('Saturn', 'שבתאי', 'Сатурн')],
];
export const planetaryNodes = planetNames.map(([id, label], order) => ({
  id: `planet-${id}`, label, kind: 'planet', layer: 'planetary', order, sourceIds: ['cicero-planets'],
  summary: L(
    `${label.en} occupies position ${order + 1} from the inside in this separately sourced classical geocentric comparison.`,
    `${label.he} נמצא במיקום ${order + 1} מבפנים בהשוואה גאוצנטרית קלאסית זו, המבוססת על מקור נפרד.`,
    `${label.ru} занимает ${order + 1}-е место изнутри в этом отдельно документированном классическом геоцентрическом сопоставлении.`
  ),
  interpretation: L(
    'This overlay reverses Cicero’s outward-to-inward list. It does not identify a planet with a Gnostic ruler and is not modern astronomy.',
    'שכבה זו הופכת את הרשימה של קיקרו, מן החוץ פנימה. היא אינה מזהה כוכב לכת עם שליט גנוסטי ואינה אסטרונומיה מודרנית.',
    'Этот слой обращает список Цицерона, идущий снаружи внутрь. Он не отождествляет планеты с гностическими правителями и не представляет современную астрономию.'
  ),
}));
export const planetarySourceId = 'cicero-planets';

export function localize(value, language = 'en') {
  if (typeof value === 'string') return value;
  return value?.[language] || value?.en || '';
}

export function getTradition(id) {
  return traditions.find((tradition) => tradition.id === id) || traditions[0];
}

export function getNode(traditionOrId, id) {
  const tradition = typeof traditionOrId === 'string' ? getTradition(traditionOrId) : traditionOrId;
  return tradition?.nodes.find((node) => node.id === id)
    || (tradition?.id === 'john' ? planetaryNodes.find((node) => node.id === id) : undefined);
}
